mapper.select:
SELECT gq.id, gq.student_id AS studentId, st.student_no AS studentNo, st.student_name AS studentName, st.department, st.major, st.admission_year AS admissionYear, gq.credit_check AS creditCheck, gq.thesis_check AS thesisCheck, gq.practice_check AS practiceCheck, gq.overall_result AS auditStatus, gq.reviewer_id AS auditorId, u.name AS auditorName, gq.review_time AS auditTime, gq.comment, gq.create_time AS createTime, gq.update_time AS updateTime, COALESCE(credit_sum.total_credits, 0) AS totalCredits, COALESCE(cfg.config_value, '30') AS requiredCredits FROM graduation_qualification gq LEFT JOIN student st ON gq.student_id = st.id LEFT JOIN `user` u ON gq.reviewer_id = u.id LEFT JOIN ( SELECT s.student_id, SUM(c.credit) AS total_credits FROM score s LEFT JOIN course c ON s.course_id = c.id WHERE s.grade IS NOT NULL AND s.grade != 'E' GROUP BY s.student_id ) credit_sum ON gq.student_id = credit_sum.student_id LEFT JOIN ( SELECT config_value FROM system_config WHERE config_key = 'graduation_required_credits' ) cfg ON 1=1
AND st.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND st.student_name LIKE CONCAT('%', #{studentName}, '%')
AND gq.overall_result = #{auditStatus}
AND st.admission_year = #{cohortYear}
AND st.department = #{department}
AND st.major = #{major}
ORDER BY gq.create_time DESC
